from collections import defaultdict

base = '/filesystem/final_batch4__electrical_task8_electrical_specs__blind'
ifc = ifcopenshell.open(f'{base}/50_bim/BLDG4410-E_RevC.ifc')

def get_props(obj):
    props = {}
    for rel in getattr(obj, 'IsDefinedBy', []):
        if rel.is_a('IfcRelDefinesByProperties'):
            pset = rel.RelatingPropertyDefinition
            if pset.is_a('IfcPropertySet'):
                for p in pset.HasProperties:
                    if p.is_a('IfcPropertySingleValue'):
                        props[p.Name] = p.NominalValue.wrappedValue if p.NominalValue else None
    return props

def poly_len(obj):
    for rep in obj.Representation.Representations:
        for item in rep.Items:
            if item.is_a('IfcPolyline'):
                pts = [p.Coordinates for p in item.Points]
                total = 0.0
                for a, b in zip(pts, pts[1:]):
                    total += math.dist(a, b)
                return total
    return 0.0

for rel in ifc.by_type('IfcRelAssignsToGroup'):
    grp = rel.RelatingGroup
    print(f'=== {grp.Name} ({grp.PredefinedType}) ===')
    by_conduit = defaultdict(list)
    for obj in rel.RelatedObjects:
        props = get_props(obj)
        # Name looks like CND-<tag>-<conduit_idx>-<seg_idx>
        parts = obj.Name.rsplit('-', 2)
        cnd_id = parts[0] + '-' + parts[1]
