def get_placement(lp):
    # returns (x, y, z) in mm
    x, y, z = 0.0, 0.0, 0.0
    curr = lp
    while curr:
        rel = curr.RelativePlacement
        if rel and rel.Location:
            coords = rel.Location.Coordinates
            x += coords[0]
            y += coords[1]
            z += coords[2] if len(coords) > 2 else 0.0
        curr = curr.PlacementRelTo
